installation.script:
#!/bin/ash
mkdir -p /mnt/server
cat > /mnt/server/index.js <<'JS'
const name = process.env.BOT_NAME || 'wss-bot';
console.log(`[bot] ${name} starting on node ${process.version}`);
console.log('[bot] online');
let ticks = 0;
setInterval(() => console.log(`[bot] heartbeat ${++ticks}`), 5000);
process.stdin.on('data', (d) => console.log(`[bot] received command: ${d.toString().trim()}`));
process.on('SIGINT', () => { console.log('[bot] shutting down'); process.exit(0); });
JS
echo 'install complete'
